style.css:
@-moz-document domain("lectio.dk") {
html, body {
        background: url("https://media.tenor.com/mvbV09bSlY8AAAAM/image-perms-kanye-west.gif") no-repeat center center fixed !important;
        background-size: cover !important;
    }

   
    .main, .content, .header, .menu, .box, .infoboks, .schedule, .timetable, table {
        background: rgba(255, 255, 255, 0.9) !important; /* Light transparency */
        border-radius: 10px !important;
        padding: 10px !important;
    }

    
    * {
        color: #222 !important;
    }

   
    .menu {
        background: rgba(0, 0, 0, 0.7) !important;
        color: white !important;
    }

  
    a {
        color: #007BFF !important; /* Blue links */
    }
}
